appearances.css:
.app{gap:4px;padding:4px;font-size:9px;display:flex!important;flex-wrap:wrap}
.grp{padding:3px 4px 4px;gap:0;border-radius:3px;min-width:0}
h3{font-size:8px;letter-spacing:.14em;margin:0 0 2px}
.grid{grid-template-columns:repeat(auto-fill,minmax(42px,1fr));gap:3px 0;align-items:start}
.grid>div{min-width:0}
.grp:nth-child(1){order:1;flex:1 1 100%}
.grp:nth-child(1) .grid{grid-template-columns:repeat(7,minmax(0,1fr))}
.grp:nth-child(3){order:2;flex:4 1 188px}
.grp:nth-child(2){order:3;flex:3 1 126px}
.grp:nth-child(8){order:4;flex:2 1 106px}
.grp:nth-child(4){order:5;flex:4 1 180px}
.grp:nth-child(5){order:6;flex:4 1 180px}
.grp:nth-child(6){order:7;flex:4 1 180px}
.grp:nth-child(7){order:8;flex:4 1 180px}
.grp:nth-child(2) .grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.grp:nth-child(8) .grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.grp:nth-child(n+3):nth-child(-n+7) .grid{grid-template-columns:repeat(4,minmax(0,1fr))}
.status{order:9;flex:1 1 100%;font-size:9px;line-height:1.2}
.k,.k[style]{display:grid!important;grid-template-columns:minmax(0,1fr)!important;justify-items:center;align-items:start;gap:0;min-width:0}
.k[data-pk-id=contour] label{font-size:6px;letter-spacing:-.06em}
.k[data-pk-id=outDrive] label{font-size:6.5px;letter-spacing:-.05em}
.k label{order:3;font-size:7px;letter-spacing:-.04em;text-align:center;max-width:100%;line-height:1.1;white-space:normal}
.k output{order:2;font-size:8px;text-align:center;line-height:1.1;white-space:nowrap}
.k .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.k .kn svg{width:100%;height:100%}
label.s{display:grid;gap:0;justify-items:center;align-content:start;padding:0 2px}
label.s select{order:1;width:100%;font-size:7px;padding:3px 0;text-indent:0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px;cursor:pointer;height:26px}
label.s span{order:2;font-size:7.5px;letter-spacing:-.03em;text-align:center;line-height:1.1;margin-top:2px}
label.c{display:grid;gap:0;justify-items:center;align-content:start;padding:0 2px}
label.c input{margin:5px 0 4px}
label.c span{font-size:7.5px;letter-spacing:-.03em;text-align:center;line-height:1.1}
